import fitz
keywords = ['nuclear','nuclear energy','nuclear power','atomic energy','fission']
doc = fitz.open('IPCC_AR6_SYR_LongerReport.pdf')
mentions = {}
for i in range(doc.page_count):
    text = doc[i].get_text("text").lower()
    for kw in keywords:
        if kw in text:
            if i+1 not in mentions:
                mentions[i+1] = []
            mentions[i+1].append(kw)
print('hits:', sorted(list(mentions.keys())))
for p in sorted(mentions.keys()):
    snippet = doc[p-1].get_text("text")[0:600]
    print(f'Page {p} snippet:', snippet.replace('\n',' ')[:300])
